	const prefix, suffix = "https://", ".corp.example"
	entries := make([]string, 0, count)
	for range count {
		entries = append(entries, prefix+strings.Repeat(string(filler), size-utf8.RuneCountInString(prefix)-utf8.RuneCountInString(suffix))+suffix)
	}
